actions.action:
// No nexus - no PA filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate PA additions
            double additions = 0.0;

            // PA Addition: Federal interest income (U.S. government obligations)
            // Tax-exempt federally but taxable in PA
            // additions += revenue.federal_bond_interest;

            // PA Addition: IRC 199A qualified business income deduction
            // PA does not allow this federal deduction
            // additions += result.section_199a_deduction;

            // PA Addition: State/local taxes deducted on federal return
            // Not deductible for PA purposes (similar to federal SALT cap)
            // additions += expense.state_local_taxes;

            apportionment.state_additions = additions;

            // Calculate PA subtractions
            double subtractions = 0.0;

            // PA Subtraction: Interest on PA state/municipal bonds
            // Taxable federally but exempt in PA
            // subtractions += revenue.pa_municipal_interest;

            // PA Subtraction: Dividend income (qualified dividends)
            // PA allows 100% dividends received deduction for qualified dividends
            // subtractions += revenue.dividend_income_qualified;

            // PA Subtraction: PA Net Operating Loss deduction
            // PA NOL rules may differ from federal
            // subtractions += result.pa_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // PA uses 8.99% flat rate (one of highest state corporate rates)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract PA state credits
            // Common PA credits: R&D, Manufacturing, Film, Job Creation, KOZ
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
